export function SemanticToken({
  semanticName = "{{semanticName}}",
  rawToken = "{{rawToken}}",
  value = "{{value}}",
  context = "{{context}}",
}) {
  let use;
  if (context === "alert") use = <div style={{ padding: "10px 12px", borderRadius: 8, background: "#ffffff", boxSizing: "border-box", fontSize: 13, borderLeft: `4px solid ${value}` }}>Something needs attention</div>;
  else if (context === "button") use = <div style={{ padding: "10px 12px", borderRadius: 8, boxSizing: "border-box", fontSize: 13, background: value, color: "#FAF7F2", fontWeight: 600, textAlign: "center" }}>Delete account</div>;
  else use = <div style={{ padding: "10px 12px", borderRadius: 8, background: "#ffffff", boxSizing: "border-box", fontSize: 13, border: `2px solid ${value}` }}>Invalid field</div>;
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 14px", display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
        <code style={{ background: "#24143012", padding: "2px 6px", borderRadius: 4, fontSize: 11 }}>{semanticName}</code> &rarr;
        <code style={{ background: "#24143012", padding: "2px 6px", borderRadius: 4, fontSize: 11 }}>{rawToken}</code> &rarr;
        <span style={{ display: "inline-block", width: 16, height: 16, borderRadius: 4, background: value }} />
      </p>
      {use}
    </div>
  );
}
